// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Capability self-description
	// (GET /api/v1)
	GetCapabilities(c *gin.Context)
	// Register a credential
	// (POST /api/v1/credentials)
	CreateCredential(c *gin.Context, params CreateCredentialParams)
	// Delete a credential
	// (DELETE /api/v1/credentials/{id})
	DeleteCredential(c *gin.Context, id CredentialId)
	// Get credential metadata (never the secret)
	// (GET /api/v1/credentials/{id})
	GetCredential(c *gin.Context, id CredentialId)
	// Query events (audit and SSE backlog)
	// (GET /api/v1/events)
	ListEvents(c *gin.Context, params ListEventsParams)
	// Stream all events (SSE)
	// (GET /api/v1/events/stream)
	StreamEvents(c *gin.Context, params StreamEventsParams)
	// List jobs
	// (GET /api/v1/jobs)
	ListJobs(c *gin.Context, params ListJobsParams)
	// Submit a job (batch install / power / discover)
	// (POST /api/v1/jobs)
	CreateJob(c *gin.Context, params CreateJobParams)
	// Get a job with its summary
	// (GET /api/v1/jobs/{id})
	GetJob(c *gin.Context, id JobId)
	// Cancel a job
	// (POST /api/v1/jobs/{id}/cancel)
	CancelJob(c *gin.Context, id JobId)
	// Stream a job's events (SSE)
	// (GET /api/v1/jobs/{id}/events)
	StreamJobEvents(c *gin.Context, id JobId, params StreamJobEventsParams)
	// List tasks of a job
	// (GET /api/v1/jobs/{id}/tasks)
	ListJobTasks(c *gin.Context, id JobId, params ListJobTasksParams)
	// Get a task with its stage details
	// (GET /api/v1/jobs/{id}/tasks/{taskId})
	GetJobTask(c *gin.Context, id JobId, taskId TaskId)
	// Retry a failed or interrupted task
	// (POST /api/v1/jobs/{id}/tasks/{taskId}/retry)
	RetryJobTask(c *gin.Context, id JobId, taskId TaskId)
	// List machines
	// (GET /api/v1/machines)
	ListMachines(c *gin.Context, params ListMachinesParams)
	// Register a machine by its out-of-band address and credential
	// (POST /api/v1/machines)
	CreateMachine(c *gin.Context, params CreateMachineParams)
	// Deregister a machine
	// (DELETE /api/v1/machines/{id})
	DeleteMachine(c *gin.Context, id MachineId)
	// Get a machine
	// (GET /api/v1/machines/{id})
	GetMachine(c *gin.Context, id MachineId)
	// Update mutable machine fields
	// (PATCH /api/v1/machines/{id})
	UpdateMachine(c *gin.Context, id MachineId)
	// Dispatch a single-machine out-of-band action
	// (POST /api/v1/machines/{id}/actions)
	PerformMachineAction(c *gin.Context, id MachineId, params PerformMachineActionParams)
	// Get a one-time KVM / virtual console URL
	// (GET /api/v1/machines/{id}/console)
	GetMachineConsole(c *gin.Context, id MachineId)
	// Resolve an install spec into a plan without installing
	// (POST /api/v1/machines/{id}/install-plan)
	CreateInstallPlan(c *gin.Context, id MachineId)
	// Get the latest disk layout snapshot
	// (GET /api/v1/machines/{id}/layout)
	GetMachineLayout(c *gin.Context, id MachineId)
	// List webhook subscriptions (no secrets)
	// (GET /api/v1/webhooks)
	ListWebhooks(c *gin.Context)
	// Subscribe an HTTP endpoint to events
	// (POST /api/v1/webhooks)
	CreateWebhook(c *gin.Context, params CreateWebhookParams)
	// Delete a webhook subscription
	// (DELETE /api/v1/webhooks/{id})
	DeleteWebhook(c *gin.Context, id string)
	// Get a webhook subscription (no secret)
	// (GET /api/v1/webhooks/{id})
	GetWebhook(c *gin.Context, id string)
	// Liveness probe (no dependency checks)
	// (GET /healthz)
	Healthz(c *gin.Context)
	// Readiness probe (database and queue reachable)
	// (GET /readyz)
	Readyz(c *gin.Context)
	// Report install completion from the target machine
	// (POST /render/{token}/complete)
	ReportInstallComplete(c *gin.Context, token string)
	// Fetch a rendered answer file by task token
	// (GET /render/{token}/{file})
	FetchAnswerFile(c *gin.Context, token string, file string)
}

